// Generates assets/ding.wav: a short two-partial bell with an exponential decay.
// Deterministic, so the shipped file can be regenerated byte-for-byte.
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const out = join(here, '..', 'assets', 'ding.wav');

const RATE = 22050;
const SECONDS = 0.72;
const frames = Math.round(RATE * SECONDS);
const samples = new Int16Array(frames);

for (let i = 0; i < frames; i += 1) {
  const t = i / RATE;
  const attack = Math.min(1, t / 0.004);
  const decay = Math.exp(-6.5 * t);
  const body =
    Math.sin(2 * Math.PI * 884 * t) * 0.62 +
    Math.sin(2 * Math.PI * 1327 * t) * 0.24 +
    Math.sin(2 * Math.PI * 2650 * t) * 0.08;
  const envelope = attack * decay;
  samples[i] = Math.max(-32767, Math.min(32767, Math.round(body * envelope * 0.55 * 32767)));
}

const dataBytes = samples.length * 2;
const buffer = Buffer.alloc(44 + dataBytes);
buffer.write('RIFF', 0, 'ascii');
buffer.writeUInt32LE(36 + dataBytes, 4);
buffer.write('WAVE', 8, 'ascii');
buffer.write('fmt ', 12, 'ascii');
buffer.writeUInt32LE(16, 16);
buffer.writeUInt16LE(1, 20); // PCM
buffer.writeUInt16LE(1, 22); // mono
buffer.writeUInt32LE(RATE, 24);
buffer.writeUInt32LE(RATE * 2, 28);
buffer.writeUInt16LE(2, 32);
buffer.writeUInt16LE(16, 34);
buffer.write('data', 36, 'ascii');
buffer.writeUInt32LE(dataBytes, 40);
Buffer.from(samples.buffer, samples.byteOffset, dataBytes).copy(buffer, 44);

mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, buffer);
console.log(`wrote ${out} (${buffer.length} bytes, ${SECONDS}s)`);
